//! What every sidebar's panels share: a panel with a title has a header on
//! the theme's raised surface, a small step apart from its body on the base
//! surface, with no line between them, and a single thin line in the theme's
//! line colour lies between one panel and the next.

use gpui_kit::component::{ActiveTheme as _, StyledExt as _, h_flex};
use gpui_kit::*;

use crate::theme;

/// A panel's header: its title, and, for a counted panel, how many rows it
/// lists, muted, at its right.
pub fn header(title: &'static str, count: Option<usize>, cx: &App) -> Div {
    h_flex()
        .flex_none()
        .justify_between()
        .gap_2()
        .px_3()
        .py_2()
        .bg(theme::color(theme::palette(cx).raised))
        .text_sm()
        .font_semibold()
        .child(title)
        .children(count.map(|count| {
            div()
                .text_xs()
                .font_normal()
                .text_color(cx.theme().muted_foreground)
                .child(count.to_string())
        }))
}

/// The line between one panel and the next.
pub fn divider(cx: &App) -> Div {
    div()
        .flex_none()
        .w_full()
        .h(px(1.))
        .bg(cx.theme().sidebar_border)
}
//! Draws a painted frame's quads, backgrounds and borders, into an image, so
//! a test can show what a window looks like where no renderer is available.
//! Text and icons aren't drawn. For looking at a frame while working on it;
//! no test keeps an image.
#![allow(dead_code)]

use gpui_kit::{Hsla, Rgba, Window};

/// Writes the window's last frame as a binary PPM at `path`.
pub fn save(window: &Window, path: &std::path::Path) {
    let (w, h, px) = pixels(window);
    let mut out = format!("P6\n{w} {h}\n255\n").into_bytes();
    for p in px {
        for c in p {
            out.push((c.clamp(0., 1.) * 255.).round() as u8);
        }
    }
    std::fs::write(path, out).unwrap();
}

/// The window's last frame, drawn: its width and height in device pixels, and
/// each pixel's red, green, and blue, row by row.
pub fn pixels(window: &Window) -> (usize, usize, Vec<[f32; 3]>) {
    let mut quads = window.painted_quads();
    quads.sort_by_key(|quad| quad.order);
    let (w, h) = quads.iter().fold((1usize, 1usize), |(w, h), q| {
        let m = &q.content_mask.bounds;
        (
            w.max((m.origin.x.0 + m.size.width.0).ceil() as usize),
            h.max((m.origin.y.0 + m.size.height.0).ceil() as usize),
        )
    });
    let (w, h) = (w.min(8000), h.min(8000));
    let mut px = vec![[0f32; 3]; w * h];
    let mut blend = |x: usize, y: usize, color: Hsla| {
        if x >= w || y >= h || color.a <= 0. {
            return;
        }
        let c: Rgba = color.into();
        let p = &mut px[y * w + x];
        let a = c.a;
        p[0] = p[0] * (1. - a) + c.r * a;
        p[1] = p[1] * (1. - a) + c.g * a;
        p[2] = p[2] * (1. - a) + c.b * a;
    };
    for q in &quads {
        let (bx0, by0) = (q.bounds.origin.x.0, q.bounds.origin.y.0);
        let (bx1, by1) = (bx0 + q.bounds.size.width.0, by0 + q.bounds.size.height.0);
        let m = &q.content_mask.bounds;
        let (x0, y0) = (bx0.max(m.origin.x.0).max(0.), by0.max(m.origin.y.0).max(0.));
        let (x1, y1) = (
            bx1.min(m.origin.x.0 + m.size.width.0),
            by1.min(m.origin.y.0 + m.size.height.0),
        );
        let bw = &q.border_widths;
        let fill = q.background.as_solid();
        for y in (y0.floor() as usize)..(y1.ceil().max(0.) as usize) {
            for x in (x0.floor() as usize)..(x1.ceil().max(0.) as usize) {
                let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
                // As the renderer does for a quad without rounded corners: a
                // pixel is border by the edges of the half of the quad it lies
                // in, so a quad no taller than its bottom border draws that
                // border in its lower half only.
                let (cx, cy) = ((bx0 + bx1) / 2., (by0 + by1) / 2.);
                let border = if fy < cy {
                    fy < by0 + bw.top.0
                } else {
                    fy > by1 - bw.bottom.0
                } || if fx < cx {
                    fx < bx0 + bw.left.0
                } else {
                    fx > bx1 - bw.right.0
                };
                if border {
                    blend(x, y, q.border_color);
                } else if let Some(fill) = fill {
                    blend(x, y, fill);
                }
            }
        }
    }
    (w, h, px)
}

//! The application's theme (see the ThemeScope): a neutral grey interface
//! defined by its dark mode, around a base of #444444, with light mode read
//! from it. The palette here is the one source of every colour; gpui-kit's
//! theme is built from it, so components with default styling follow it, and
//! what draws its own colours asks for a role here.

use std::rc::Rc;

use gpui_kit::component::tag::{Tag, TagVariant};
use gpui_kit::component::{ActiveTheme as _, Theme, ThemeConfig, ThemeMode, ThemeRegistry};
use gpui_kit::*;
use serde_json::{Map, Value, json};

/// Every role of the theme, for one mode, as 0xRRGGBB.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Palette {
    /// Where content is read or written: the editor, code, answers.
    pub well: u32,
    /// Text inputs, lists, trees.
    pub recessed: u32,
    /// The window and its panels.
    pub base: u32,
    /// Buttons, tab bars, headers, cards.
    pub raised: u32,
    pub hover: u32,
    pub pressed: u32,
    /// A selected row or tab without focus.
    pub selected: u32,
    /// Menus, popovers, tooltips, inset panels.
    pub overlay: u32,
    /// The ribbon's command area, and its open tabs, which read as one piece
    /// with it.
    pub ribbon: u32,
    /// The ribbon's row of tabs, a step from its command area: lighter in dark
    /// mode, darker in light mode. Also the dividers between its groups.
    pub ribbon_tabs: u32,
    pub text: u32,
    /// What the spec calls muted.
    pub text_secondary: u32,
    /// Dimmer than muted: help text, placeholders.
    pub text_tertiary: u32,
    pub text_disabled: u32,
    /// Dividers between areas and rows.
    pub line: u32,
    /// The border of controls, inputs, and floating surfaces.
    pub edge: u32,
    /// Focus, selected tabs' underlines, links, accent text.
    pub accent: u32,
    /// Primary buttons, a selected item in a focused list.
    pub accent_fill: u32,
    pub success: u32,
    pub warning: u32,
    pub error: u32,
    pub purple: u32,
    pub cyan: u32,
    pub orange: u32,
    /// How much black dims the window behind a modal surface.
    pub dim: f32,
    /// How much white lights, and black shades, a bevel's edges.
    pub bevel_light: f32,
    pub bevel_shade: f32,
}

