112	/// Why `name` can't be given to something in `dir`, other than `renaming`.
113	pub fn name_problem(name: &str, dir: &Path, renaming: Option<&Path>) -> Option<&'static str> {
114	    if name.is_empty() {
115	        return Some("Give it a name");
116	    }
117	    if name.contains(['/', '\\']) {
118	        return Some("A name can't contain a slash");
119	    }
120	    if name == "." || name == ".." {
121	        return Some("That name isn't allowed");
122	    }
123	    let path = dir.join(name);
124	    if renaming != Some(path.as_path()) && path.symlink_metadata().is_ok() {
125	        return Some("Something with that name is already here");
126	    }
127	    None
128	}
