163	    pub fn new(cx: &mut Context<Self>) -> Self {
164	        let tree = cx.new(|cx| TreeState::new(cx));
165	        let subscriptions = vec![
166	            cx.observe_global::<ProjectDirectory>(|this, cx| {
167	                this.open(ProjectDirectory::get(cx), cx)
168	            }),
169	            cx.subscribe(&tree, |this, _, event: &TreeEvent, cx| {
170	                this.on_tree_event(event, cx)
171	            }),
172	        ];
173	
