175	            root: None,
176	            listings: HashMap::new(),
177	            expanded: HashSet::new(),
178	            tree,
179	            watcher: None,
180	            watched: HashSet::new(),
181	            _refresh: None,
182	            git: None,
183	            editing: None,
184	            select_when_listed: None,
185	            menu: None,
186	            _git_refresh: Task::ready(()),
187	            left: HashMap::new(),
188	            _subscriptions: subscriptions,
