194	    fn open(&mut self, root: Option<PathBuf>, cx: &mut Context<Self>) {
195	        if root == self.root {
196	            return;
197	        }
198	        // The project left keeps how it was, for when it's back.
199	        if let Some(left) = self.root.take() {
200	            let selected = self
201	                .tree
202	                .read(cx)
203	                .selected_item()
204	                .map(|item| PathBuf::from(item.id.as_ref()));
205	            self.left
206	                .insert(left, (std::mem::take(&mut self.expanded), selected));
207	        }
208	        let (expanded, selected) = root
209	            .as_ref()
210	            .and_then(|root| self.left.remove(root))
211	            .unwrap_or_default();
212	        self.root = root.clone();
213	        self.editing = None;
214	        self.listings.clear();
215	        self.expanded = expanded;
216	        self.select_when_listed = selected;
217	        self.watched.clear();
218	        (self.watcher, self._refresh) = match &root {
219	            Some(_) => self.start_watching(cx),
220	            None => (None, None),
221	        };
222	        self.rebuild(cx);
223	        self.git = None;
224	        self._git_refresh = match root.clone() {
225	            Some(root) => self.watch_git(root, cx),
226	            None => Task::ready(()),
227	        };
228	        if let Some(root) = root {
229	            self.load(root, cx);
230	            // Its expanded folders are read again, shown open once listed.
231	            for folder in self.expanded.clone() {
232	                self.load(folder, cx);
233	            }
234	        }
235	        cx.notify();
236	    }
