238	    /// Reads the project's git status straight away, then again every so
239	    /// often, showing it whenever it changes.
240	    fn watch_git(&self, root: PathBuf, cx: &mut Context<Self>) -> Task<()> {
241	        cx.spawn(async move |this, cx| {
242	            loop {
243	                let status = cx
244	                    .background_spawn({
245	                        let root = root.clone();
246	                        async move { GitStatus::read(&root) }
247	                    })
248	                    .await;
249	                let updated = this.update(cx, |this, cx| {
250	                    if this.root.as_ref() == Some(&root) && this.git != status {
251	                        this.git = status;
252	                        cx.notify();
253	                    }
254	                });
255	                if updated.is_err() {
256	                    break;
257	                }
258	                cx.background_executor().timer(GIT_REFRESH_INTERVAL).await;
259	            }
260	        })
261	    }
