263	    fn on_tree_event(&mut self, event: &TreeEvent, cx: &mut Context<Self>) {
264	        match event {
265	            TreeEvent::Expanded(id) => {
266	                let path = PathBuf::from(id.as_ref());
267	                self.expanded.insert(path.clone());
268	                if !self.listings.contains_key(&path) {
269	                    self.load(path, cx);
270	                }
271	            }
272	            TreeEvent::Collapsed(id) => {
