278	    /// Creates a watcher whose reports re-read the folders they touch.
279	    fn start_watching(
280	        &self,
281	        cx: &mut Context<Self>,
282	    ) -> (Option<RecommendedWatcher>, Option<Task<()>>) {
283	        // Collected on a timer rather than awaited: the watcher reports from
284	        // its own thread, which must not wake app tasks (tests forbid it).
285	        let (tx, rx) = mpsc::channel();
286	        let watcher = notify::recommended_watcher(move |event: notify::Result<Event>| {
287	            let Ok(event) = event else { return };
288	            // Reads and content edits leave a folder's entries as they were.
289	            if matches!(
290	                event.kind,
291	                EventKind::Access(_) | EventKind::Modify(ModifyKind::Data(_))
292	            ) {
293	                return;
294	            }
295	            for path in event.paths {
296	                // An entry changed within its parent; a watched folder itself
297	                // may also have gone.
298	                if let Some(parent) = path.parent() {
299	                    tx.send(parent.to_path_buf()).ok();
300	                }
301	                tx.send(path).ok();
302	            }
303	        });
304	        let Ok(watcher) = watcher else {
305	            return (None, None);
306	        };
307	
308	        let refresh = cx.spawn(async move |this, cx| {
309	            loop {
310	                cx.background_executor().timer(REFRESH_INTERVAL).await;
311	                let dirs = rx.try_iter().collect::<HashSet<_>>();
312	                if dirs.is_empty() {
313	                    continue;
314	                }
315	                let updated = this.update(cx, |this, cx| {
316	                    for dir in dirs {
317	                        if this.listings.contains_key(&dir) {
318	                            this.load(dir, cx);
319	                        }
320	                    }
321	                });
322	                if updated.is_err() {
323	                    break;
324	                }
325	            }
326	        });
327	        (Some(watcher), Some(refresh))
328	    }
