330	    /// Reads a folder in the background, then shows its entries.
331	    fn load(&mut self, dir: PathBuf, cx: &mut Context<Self>) {
332	        // Watched before it is read, so no change slips in between.
333	        if let Some(watcher) = &mut self.watcher
334	            && !self.watched.contains(&dir)
335	            && watcher.watch(&dir, RecursiveMode::NonRecursive).is_ok()
336	        {
337	            self.watched.insert(dir.clone());
338	        }
339	
340	        let root = self.root.clone();
341	        let read = cx.background_spawn({
342	            let dir = dir.clone();
343	            async move { read_dir(&dir) }
344	        });
345	        cx.spawn(async move |this, cx| {
346	            let listing = read.await;
347	            this.update(cx, |this, cx| {
348	                // Another project may have been opened while the folder was read.
349	                if this.root != root {
350	                    return;
351	                }
352	                if this.listings.get(&dir) == Some(&listing) {
353	                    return;
354	                }
355	                this.forget_vanished_folders(&dir, &listing);
356	                // A folder left expanded that has come back is read again.
357	                let reappeared = listing.iter().flatten().filter(|entry| {
358	                    entry.is_dir
359	                        && this.expanded.contains(&entry.path)
360	                        && !this.listings.contains_key(&entry.path)
361	                });
362	                let reappeared = reappeared
363	                    .map(|entry| entry.path.clone())
364	                    .collect::<Vec<_>>();
365	                this.listings.insert(dir, listing);
366	                this.rebuild(cx);
367	                for path in reappeared {
368	                    this.load(path, cx);
369	                }
370	            })
371	            .ok();
372	        })
373	        .detach();
374	    }
