376	    /// Drops what was read and watched beneath the folders `dir` no longer
377	    /// lists, so they are read afresh if they come back.
378	    fn forget_vanished_folders(&mut self, dir: &Path, listing: &Listing) {
379	        let Some(Ok(previous)) = self.listings.get(dir) else {
380	            return;
381	        };
382	        let current = listing.as_ref().map(Vec::as_slice).unwrap_or_default();
383	        let vanished = previous
384	            .iter()
385	            .filter(|old| {
386	                old.is_dir && !current.iter().any(|new| new.is_dir && new.path == old.path)
387	            })
388	            .map(|old| old.path.clone())
389	            .collect::<Vec<_>>();
390	        for gone in vanished {
391	            self.listings.retain(|path, _| !path.starts_with(&gone));
392	            self.watched.retain(|path| {
393	                let keep = !path.starts_with(&gone);
394	                if !keep && let Some(watcher) = &mut self.watcher {
395	                    watcher.unwatch(path).ok();
396	                }
397	                keep
398	            });
399	        }
400	    }
