402	    fn rebuild(&mut self, cx: &mut Context<Self>) {
403	        let items = match &self.root {
404	            Some(root) => self.children_of(root),
405	            None => Vec::new(),
406	        };
407	        let select = self
408	            .select_when_listed
409	            .as_ref()
410	            .map(|path| SharedString::from(path.to_string_lossy().into_owned()));
411	        let selected_now = self.tree.update(cx, |tree, cx| {
412	            // Replacing the items clears the selection; keep it on the same path.
413	            let selected = tree.selected_item().map(|item| item.id.clone());
414	            tree.set_items(items, cx);
415	            match select.and_then(|id| tree.index_of(&id)) {
416	                Some(ix) => {
417	                    tree.set_selected_index(Some(ix), cx);
418	                    true
419	                }
420	                None => {
421	                    if let Some(ix) = selected.and_then(|id| tree.index_of(&id)) {
422	                        tree.set_selected_index(Some(ix), cx);
423	                    }
424	                    false
425	                }
426	            }
427	        });
428	        if selected_now {
429	            self.select_when_listed = None;
430	        }
431	    }
