708	    fn children_of(&self, dir: &Path) -> Vec<TreeItem> {
709	        let placeholder = |label: SharedString| {
710	            // Keyed under the folder so it never collides with a real path.
711	            TreeItem::new(format!("{}\0", dir.display()), label).disabled(true)
712	        };
713	        // A new file or folder being named has a row of its own at the top.
714	        let new_row = self
715	            .editing
716	            .as_ref()
717	            .filter(|editing| {
718	                matches!(&editing.naming, Naming::NewFile(new) | Naming::NewFolder(new) if new == dir)
719	            })
720	            .map(|editing| TreeItem::new(editing.naming.item_id(), ""));
721	        let children = match self.listings.get(dir) {
722	            None => vec![placeholder("Loading…".into())],
723	            Some(Err(err)) => vec![placeholder(err.clone())],
724	            Some(Ok(entries)) if entries.is_empty() => vec![placeholder("Empty".into())],
725	            Some(Ok(entries)) => entries
726	                .iter()
727	                .map(|entry| {
728	                    let item = TreeItem::new(
729	                        entry.path.to_string_lossy().into_owned(),
730	                        entry.name.clone(),
731	                    );
732	                    if entry.is_dir {
733	                        item.expanded(self.expanded.contains(&entry.path))
734	                            .children(self.children_of(&entry.path))
735	                    } else {
736	                        item
737	                    }
738	                })
739	                .collect(),
740	        };
741	        match new_row {
742	            Some(row) => std::iter::once(row)
743	                .chain(children.into_iter().filter(|item| !item.is_disabled()))
744	                .collect(),
745	            None => children,
746	        }
747	    }
748	}
