750	fn read_dir(dir: &Path) -> Listing {
751	    let mut entries = std::fs::read_dir(dir)
752	        .map_err(|err| SharedString::from(format!("Unreadable: {err}")))?
753	        .filter_map(|entry| entry.ok())
754	        .filter(|entry| !HIDDEN_NAMES.iter().any(|name| entry.file_name() == *name))
755	        .map(|entry| {
756	            let path = entry.path();
757	            DirEntry {
758	                name: entry.file_name().to_string_lossy().into_owned().into(),
759	                // Follows symlinks, so a link to a folder is listed as a folder.
760	                is_dir: path.is_dir(),
761	                path,
762	            }
763	        })
764	        .collect::<Vec<_>>();
765	    entries.sort_by_cached_key(|entry| (!entry.is_dir, entry.name.to_lowercase()));
766	    Ok(entries)
767	}
