491	            self.left_messages.insert(left, message);
492	        }
493	        let message = root
494	            .as_ref()
495	            .and_then(|root| self.left_messages.remove(root))
496	            .unwrap_or_default();
497	        if self.message.read(cx).value() != message.as_str() {
498	            self.message
499	                .update(cx, |editor, cx| editor.set_value(message, window, cx));
500	        }
501	        self.root = root.clone();
502	        self.summary = None;
503	        self._refresh = match root {
504	            Some(root) => cx.spawn(async move |this, cx| {
505	                loop {
506	                    let summary = cx
507	                        .background_spawn({
508	                            let root = root.clone();
509	                            async move { Summary::read(&root) }
510	                        })
511	                        .await;
512	                    let updated = this.update(cx, |this, cx| {
513	                        if this.root.as_ref() == Some(&root) && this.summary != summary {
514	                            this.summary = summary;
515	                            cx.notify();
516	                        }
517	                    });
518	                    if updated.is_err() {
519	                        break;
520	                    }
521	                    cx.background_executor().timer(REFRESH_INTERVAL).await;
522	                }
523	            }),
524	            None => Task::ready(()),
525	        };
526	        cx.notify();
527	    }
528	
529	    /// Reads the summary again straight away.
530	    fn refresh(&mut self, cx: &mut Context<Self>) {
531	        let Some(root) = self.root.clone() else {
532	            return;
533	        };
534	        cx.spawn(async move |this, cx| {
535	            let summary = cx
536	                .background_spawn({
537	                    let root = root.clone();
538	                    async move { Summary::read(&root) }
539	                })
540	                .await;
541	            this.update(cx, |this, cx| {
542	                if this.root.as_ref() == Some(&root) {
543	                    this.summary = summary;
544	                    cx.notify();
545	                }
546	            })
547	            .ok();
548	        })
549	        .detach();
550	    }
551	
552	    /// Runs `work` in the background as `busy`, then shows `done` or why it
553	    /// failed, and reads the summary again.
554	    fn run<T: Send + 'static>(
555	        &mut self,
556	        busy: Busy,
557	        work: impl FnOnce(&Path) -> Result<T> + Send + 'static,
558	        done: impl FnOnce(&mut Self, T, &mut Window, &mut Context<Self>) + 'static,
559	        window: &mut Window,
560	        cx: &mut Context<Self>,
561	    ) {
562	        let Some(root) = self.root.clone().filter(|_| self.busy.is_none()) else {
563	            return;
564	        };
565	        self.busy = Some(busy);
566	        cx.notify();
567	        let task = cx.background_spawn(async move { work(&root) });
568	        cx.spawn_in(window, async move |this, cx| {
569	            let result = task.await;
570	            this.update_in(cx, |this, window, cx| {
571	                this.busy = None;
572	                match result {
573	                    Ok(value) => done(this, value, window, cx),
574	                    Err(err) => {
575	                        let title = match busy {
576	                            Busy::Commit => "Could not commit",
577	                            Busy::Push => "Could not push",
578	                            Busy::Pull => "Could not pull",
579	                            Busy::Generate => "Could not write a commit message",
580	                        };
581	                        window.push_notification(
582	                            Notification::error(format!("{err:#}")).title(title),
583	                            cx,
584	                        );
585	                    }
586	                }
587	                this.refresh(cx);
588	                cx.notify();
589	            })
590	            .ok();
591	        })
592	        .detach();
593	    }
594	
595	    /// Commits with the message typed and the commit notes beneath it.
596	    pub fn commit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
597	        let message =
598	            commit_notes::message(&self.message.read(cx).value(), &self.current_notes(cx));
599	        if message.is_empty() {
600	            return;
601	        }
602	        self.run(
603	            Busy::Commit,
604	            move |root| commit(root, &message),
605	            |this, (), window, cx| {
606	                this.message
607	                    .update(cx, |editor, cx| editor.set_value("", window, cx));
608	                // The notes went into the commit.
609	                if let Some(root) = &this.root {
610	                    commit_notes::save(root, &[]).ok();
611	                }
612	                commit_notes::changed(cx);
613	                window.push_notification(Notification::success("Committed"), cx);
614	            },
615	            window,
616	            cx,
617	        );
618	    }
619	
620	    fn push(&mut self, window: &mut Window, cx: &mut Context<Self>) {
621	        let has_upstream = self
622	            .summary
623	            .as_ref()
624	            .is_some_and(|summary| summary.has_upstream);
625	        self.run(
626	            Busy::Push,
627	            move |root| push(root, has_upstream),
628	            |_, (), window, cx| window.push_notification(Notification::success("Pushed"), cx),
629	            window,
630	            cx,
631	        );
632	    }
633	
634	    fn pull(&mut self, window: &mut Window, cx: &mut Context<Self>) {
635	        self.run(
636	            Busy::Pull,
637	            pull,
638	            |_, pulled, window, cx| {
639	                let message = match pulled {
640	                    Pulled::UpToDate => "Already up to date",
641	                    Pulled::FastForwarded => "Pulled",
642	                    Pulled::Merged => "Pulled and merged",
643	                };
644	                window.push_notification(Notification::success(message), cx)
645	            },
646	            window,
647	            cx,
648	        );
649	    }
650	
651	    fn generate(&mut self, window: &mut Window, cx: &mut Context<Self>) {
652	        self.run(
653	            Busy::Generate,
654	            generate_message,
655	            |this, message, window, cx| {
656	                this.message
657	                    .update(cx, |editor, cx| editor.set_value(message, window, cx));
658	            },
659	            window,
660	            cx,
661	        );
662	    }
