669	    #[cfg(test)]
670	    pub fn set_message(&mut self, text: &str, window: &mut Window, cx: &mut Context<Self>) {
671	        self.message
672	            .update(cx, |editor, cx| editor.set_value(text, window, cx));
673	        cx.notify();
674	    }
