                    frame.at(gpui_kit::point(x, y)),
                    expected,
                    "{mode:?}: {dy}px from the edge between the tree and the git panel"
                );
            }
        })
        .unwrap();
    }
    std::fs::remove_dir_all(&dir).ok();
}

