fn bg_color(&self, outline: bool, cx: &mut App) -> Background {
    if outline {
        return self.outline_background(ButtonStyleState::Normal, cx);
    }

    match self {
        Self::Default => cx.theme().tokens.button.into(),
        Self::Primary => cx.theme().tokens.button_primary.into(),
        Self::Secondary => cx.theme().tokens.button_secondary.into(),
        Self::Danger => cx.theme().tokens.button_danger.into(),
        Self::Warning => cx.theme().tokens.button_warning.into(),
        Self::Success => cx.theme().tokens.button_success.into(),
        Self::Info => cx.theme().tokens.button_info.into(),
        Self::Ghost | Self::Link | Self::Text => cx.theme().transparent.into(),
        Self::Custom(colors) => colors.color.mix_oklab(cx.theme().transparent, 0.2).into(),
    }
}

fn text_color(&self, outline: bool, cx: &mut App) -> Hsla {
    match self {
        Self::Default => cx.theme().button_foreground,
        Self::Primary => {
            if outline {
                cx.theme().primary
                cx.theme().button_warning
            }
        }
        Self::Success => {
            if outline {
                cx.theme().success.mix_oklab(transparent_white(), 0.4)
            } else {
                cx.theme().button_success
            }
        }
        Self::Ghost | Self::Link | Self::Text => cx.theme().transparent,
        Self::Custom(colors) => {
            if outline {
                colors.color.mix_oklab(transparent_white(), 0.4)
            } else {
                colors.color
            }
        }
    }
}

    fn render_command(
        &self,
        command: Command,
        size: CommandSize,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let colors = command_colors(cx);
        let rest = command_shades(cx).0;
        let button_with = |id: ElementId, icon: IconName, label: SharedString| {
            // gpui-kit keeps only a fifth of a custom button's resting colour,
            // so the colour is given to the button itself; its hover and
            // pressed colours are taken whole.
            let button = Button::new(id)
                .custom(colors)
                .rounded(ButtonRounded::None)
                .bg(rest);
            match size {
                // Slim fills its column; small, in a row, never stretches.
                CommandSize::Slim | CommandSize::Small => button
                    .small()
                    .map(|button| match size {
                        CommandSize::Small => button.h(SMALL_HEIGHT).flex_none(),
                        _ => button.h(SLIM_HEIGHT).w_full(),
                    })
                    .px_2()
                    .icon(Icon::new(icon).with_size(Size::Small))
                    .label(label),
                // Its small icon centred above its label, the pair centred in
                // the two slim buttons' height its column gives it, rather
                // than the height a button takes by default.
                CommandSize::Full => button.flex_none().h_auto().px_2().child(
                    v_flex()
                        .items_center()
                        .gap_1p5()
                        .child(Icon::new(icon).with_size(Size::Small))
                        .child(div().text_sm().child(label)),
                ),
            }
        };
        let button = |id: &'static str, icon: IconName, label: SharedString| {
            button_with(id.into(), icon, label)
        };
        match command {
            Command::FindHowToRun => code_tab::find_how_to_run(&button_with, cx),
            Command::FindRunAgain => code_tab::find_again(&button_with, cx),
            Command::RunTarget(ix) => code_tab::run_target(ix, &button_with, cx),
            Command::NewProject => project_tab::new_project(button),
            Command::OpenProject => project_tab::open_project(button),
